static void check(hipError_t e, const char *msg) {
    if (e != hipSuccess) { fprintf(stderr, "%s: %s\n", msg, hipGetErrorString(e)); exit(1); }
}

int main() {
    const uint32_t out_dim = 1024, in_dim = 256, n_tok = 256;
    const uint32_t n_blocks = in_dim / 32;
    const uint64_t row_bytes = (uint64_t)n_blocks * 34u;

    std::vector<unsigned char> h_w((size_t)out_dim * row_bytes);
    std::vector<float> h_x((size_t)n_tok * in_dim);
    srand(42);
    for (auto &v : h_x) v = ((float)(rand() % 2000) - 1000.0f) / 1000.0f;
    std::vector<float> h_scale(out_dim * n_blocks);
    std::vector<int8_t> h_q((size_t)out_dim * n_blocks * 32);
    for (auto &s : h_scale) s = ((float)(rand() % 100) + 1.0f) / 500.0f;
    for (auto &q : h_q) q = (int8_t)((rand() % 255) - 127);
    for (uint32_t r = 0; r < out_dim; r++) {
        for (uint32_t b = 0; b < n_blocks; b++) {
            unsigned char *bp = h_w.data() + (uint64_t)r * row_bytes + (uint64_t)b * 34u;
            _Float16 sc = (_Float16)h_scale[r * n_blocks + b];
            uint16_t sc_bits; memcpy(&sc_bits, &sc, 2);
            memcpy(bp, &sc_bits, 2);
            memcpy(bp + 2, &h_q[(size_t)(r * n_blocks + b) * 32], 32);
        }
    }

    // CPU reference
    std::vector<float> h_ref((size_t)n_tok * out_dim, 0.0f);
    for (uint32_t t = 0; t < n_tok; t++) {
        for (uint32_t r = 0; r < out_dim; r++) {
            double acc = 0.0;
            for (uint32_t b = 0; b < n_blocks; b++) {
                float sc = h_scale[r * n_blocks + b];
                for (uint32_t kk = 0; kk < 32; kk++) {
                    int8_t q = h_q[(size_t)(r * n_blocks + b) * 32 + kk];
                    acc += (double)(sc * (float)(int)q) * (double)h_x[(size_t)t * in_dim + b * 32 + kk];
                }
            }
            h_ref[(size_t)t * out_dim + r] = (float)acc;
        }
    }

    unsigned char *d_w; float *d_x, *d_out;
    check(hipMalloc(&d_w, h_w.size()), "malloc w");
    check(hipMalloc(&d_x, h_x.size() * sizeof(float)), "malloc x");
    check(hipMalloc(&d_out, (size_t)n_tok * out_dim * sizeof(float)), "malloc out");
    check(hipMemcpy(d_w, h_w.data(), h_w.size(), hipMemcpyHostToDevice), "cpy w");
    check(hipMemcpy(d_x, h_x.data(), h_x.size() * sizeof(float), hipMemcpyHostToDevice), "cpy x");

    dim3 grid((out_dim + 63) / 64, (n_tok + 63) / 64, 1);
    std::vector<float> h_out((size_t)n_tok * out_dim);

    auto run_and_report = [&](const char *label, void (*kfn)(float*, const unsigned char*, const float*, uint32_t, uint32_t, uint32_t, uint64_t)) {
        check(hipMemset(d_out, 0, (size_t)n_tok * out_dim * sizeof(float)), "memset");
        hipLaunchKernelGGL(kfn, grid, 128, 0, 0, d_out, d_w, d_x, n_tok, in_dim, out_dim, row_bytes);
        check(hipDeviceSynchronize(), "sync");
        check(hipGetLastError(), "launch");
        check(hipMemcpy(h_out.data(), d_out, h_out.size() * sizeof(float), hipMemcpyDeviceToHost), "cpy out");
        double max_abs = 0, sum_abs = 0, max_rel = 0;
        for (size_t i = 0; i < h_out.size(); i++) {
            double d = fabs((double)h_out[i] - (double)h_ref[i]);
            max_abs = std::max(max_abs, d);
            sum_abs += d;
            double denom = fabs((double)h_ref[i]) + 1e-6;
            max_rel = std::max(max_rel, d / denom);
        }
        printf("%-10s max_abs=%.6f mean_abs=%.6f max_rel=%.6f  sample: out[0]=%.6f ref[0]=%.6f\n",
               label, max_abs, sum_abs / h_out.size(), max_rel, h_out[0], h_ref[0]);
    };

    run_and_report("candA", kernel_candA);
    run_and_report("candB", kernel_candB);
    run_and_report("candC", kernel_candC);
    return 0;
}

