            frag_a a;
            rocwmma::load_matrix_sync(a, &shWA[warp_id][0][0], 16);
#pragma unroll
            for (uint32_t ntile = 0; ntile < N_TILES_PER_WARP; ntile++) {
                frag_b b;
                rocwmma::load_matrix_sync(b, (const half *)(lds_x + ntile * 16u * K_TILE + half_i * 16u), K_TILE);
