// Standalone correctness microbenchmark for the gfx12 (RDNA4) WMMA v2 port
// of matmul_q8_0_f32_batch_wmma_4w_kernel. Tests three candidate fragment
// layouts against a CPU reference, without loading the full 86GB model.
#include <hip/hip_runtime.h>
#include <rocwmma/rocwmma-version.hpp>
#include <rocwmma/rocwmma.hpp>
